(6287889, 930789, 23484, '<td valign="top">The mist really adds to the effect. Nice shot.</td>', 'The mist really adds to the effect. Nice shot.', '2011-01-19 07:05:18.000000', NULL, 1),
(6287891, 930695, 23484, '<td valign="top">This has a great spooky look to it. Good job.</td>', 'This has a great spooky look to it. Good job.', '2011-01-19 07:06:34.000000', NULL, 1),
(6287892, 930472, 23484, '<td valign="top">Very cool shot and great perspective.</td>', 'Very cool shot and great perspective.', '2011-01-19 07:07:45.000000', NULL, 1),
(6287893, 930747, 23484, '<td valign="top">The reflection is great.</td>', 'The reflection is great.', '2011-01-19 07:08:08.000000', NULL, 1),
(6287896, 930696, 23484, '<td valign="top">Is it a VDB?</td>', 'Is it a VDB?', '2011-01-19 07:09:04.000000', NULL, 1),
(6287904, 930715, 108069, '<td valign="top">Great idea and I really like the composition and framing, but I think it needs to be sharper. Possibly you got too close and slipped inside of the focusing range?</td>', 'Great idea and I really like the composition and framing, but I think it needs to be sharper. Possibly you got too close and slipped inside of the focusing range?', '2011-01-19 07:16:03.000000', NULL, 1),
(6287905, 930647, 108069, '<td valign="top">Nice composition, lighting and focal depth. Very nice image.</td>', 'Nice composition, lighting and focal depth. Very nice image.', '2011-01-19 07:16:53.000000', NULL, 1),
(6287912, 930430, 108069, '<td valign="top">Wildly dramatic scene. Very nice leading line and wonderful depth into the clouds and sky. Closest bits to the lens seem slightly OOF which doesn''t hurt it, but you might try hyperfocal focusing next time to give you the greatest range. Great shot.</td>', 'Wildly dramatic scene. Very nice leading line and wonderful depth into the clouds and sky. Closest bits to the lens seem slightly OOF which doesn''t hurt it, but you might try hyperfocal focusing next time to give you the greatest range. Great shot.', '2011-01-19 07:24:34.000000', NULL, 1),
(6287914, 930390, 108069, '<td valign="top">Beautiful stark drama throughout this entire image. Vast, powerful. Separate but together. Awesome tones. Outstanding image.</td>', 'Beautiful stark drama throughout this entire image. Vast, powerful. Separate but together. Awesome tones. Outstanding image.', '2011-01-19 07:31:31.000000', NULL, 1),
(6287916, 930060, 108069, '<td valign="top">Wonderful composition. Nice story in this. Red bag pops amid the faded interior. Excellent photo.</td>', 'Wonderful composition. Nice story in this. Red bag pops amid the faded interior. Excellent photo.', '2011-01-19 07:32:55.000000', NULL, 1),
(6287918, 930542, 108069, '<td valign="top">Surreal shot. Dramatic sky, recent rain, white picket fence, the fish eye distorting it all, and the poodle in to inspect the scene. Wonderful tones. Extremely interesting.</td>', 'Surreal shot. Dramatic sky, recent rain, white picket fence, the fish eye distorting it all, and the poodle in to inspect the scene. Wonderful tones. Extremely interesting.', '2011-01-19 07:36:26.000000', NULL, 1),
(6287923, 930594, 108069, '<td valign="top">Subtle, peaceful beauty to this. I see those clouds and I think I would have tried to get some drama out of them and missed the moment, as she is literally keeping the peace in this photo. Very nice composition. Well done.</td>', 'Subtle, peaceful beauty to this. I see those clouds and I think I would have tried to get some drama out of them and missed the moment, as she is literally keeping the peace in this photo. Very nice composition. Well done.', '2011-01-19 07:45:41.000000', NULL, 1),
(6287928, 930711, 124982, '<td valign="top">Looks to be a great picture...unfortunately it seems a little out of focus...maybe you were hand-holding the camera?</td>', 'Looks to be a great picture...unfortunately it seems a little out of focus...maybe you were hand-holding the camera?', '2011-01-19 07:51:04.000000', NULL, 1),
(6287930, 930705, 108069, '<td valign="top">Wonderful composition and tones. B&amp;W was a wise choice. Great photo.</td>', 'Wonderful composition and tones. B&W was a wise choice. Great photo.', '2011-01-19 07:52:29.000000', NULL, 1),
(6287931, 930403, 124982, '<td valign="top">Very pretty colors. Would have preferred the background to be more blurred, it''s quite distracting.</td>', 'Very pretty colors. Would have preferred the background to be more blurred, it''s quite distracting.', '2011-01-19 07:52:30.000000', NULL, 1),
(6287936, 930807, 124982, '<td valign="top">Topaz simplify?</td>', 'Topaz simplify?', '2011-01-19 08:00:04.000000', NULL, 1),
(6287939, 930390, 124982, '<td valign="top">The atmosphere on this picture is incredible. Was this taken with IR or an IR filter?</td>', 'The atmosphere on this picture is incredible. Was this taken with IR or an IR filter?', '2011-01-19 08:03:56.000000', NULL, 1),
(6287960, 930711, 124779, '<td valign="top">could be more natural</td>', 'could be more natural', '2011-01-19 08:15:22.000000', NULL, 1),
(6287961, 930258, 124779, '<td valign="top">too much editing</td>', 'too much editing', '2011-01-19 08:15:48.000000', NULL, 1),
(6287963, 930373, 124779, '<td valign="top">what is this ...</td>', 'what is this ...', '2011-01-19 08:16:26.000000', NULL, 1),
(6287965, 930322, 124779, '<td valign="top">that red dot ....</td>', 'that red dot ....', '2011-01-19 08:17:25.000000', NULL, 1),
(6287978, 930065, 10785, '<td valign="top">Love the saturated color and the golden light!</td>', 'Love the saturated color and the golden light!', '2011-01-19 08:22:51.000000', NULL, 1),
(6287982, 930639, 10785, '<td valign="top">All the lines create a superb composition. They really need to be perfectly vertical to be a 10 and a blue ribbon winner! Here the angle of the shot looking up has given the lines of the building a tilt. Getting higher and shooting straight on may not have been possible though. The photo looks a hair out of horizontal rotation too. Excellent color and contrast. Great saturated light with the blue windows cooling it down.</td>', 'All the lines create a superb composition. They really need to be perfectly vertical to be a 10 and a blue ribbon winner! Here the angle of the shot looking up has given the lines of the building a tilt. Getting higher and shooting straight on may not have been possible though. The photo looks a hair out of horizontal rotation too. Excellent color and contrast. Great saturated light with the blue windows cooling it down.', '2011-01-19 08:25:44.000000', NULL, 1),
(6287984, 930379, 108069, '<td valign="top">Great shot, great entry. Nice sepia tones. Well done.</td>', 'Great shot, great entry. Nice sepia tones. Well done.', '2011-01-19 08:26:25.000000', NULL, 1),
(6287993, 930623, 108069, '<td valign="top">Cute scene. I don''t imagine this will seal the deal with the voters, but it''s a very cute scene. Not voting, just blubbering.</td>', 'Cute scene. I don''t imagine this will seal the deal with the voters, but it''s a very cute scene. Not voting, just blubbering.', '2011-01-19 08:28:38.000000', NULL, 1),
(6287994, 930808, 10785, '<td valign="top">Awesome perspective. The shot overall looks slightly blurry and there is a blue cast over the picture. Also looks like the building outline suffers from some mean chromatic abberation or possibly the outline of the building was selected and the sky was made to look blurry.</td>', 'Awesome perspective. The shot overall looks slightly blurry and there is a blue cast over the picture. Also looks like the building outline suffers from some mean chromatic abberation or possibly the outline of the building was selected and the sky was made to look blurry.', '2011-01-19 08:28:58.000000', NULL, 1),
(6287995, 930799, 108069, '<td valign="top">The angle seems a little awkward to me, but it''s a good idea. Maybe a bit of contrast work as well to combat the haze of the day.</td>', 'The angle seems a little awkward to me, but it''s a good idea. Maybe a bit of contrast work as well to combat the haze of the day.', '2011-01-19 08:30:16.000000', NULL, 1),
(6287996, 930504, 10785, '<td valign="top">Good texture and a rugged portrait! It seems you have caught the gentleman during a pause in the action. With the composition you have created, I would like to see the man intentionally looking into the distance or in action somehow focused in the direction he is looking. He just seems to be contemplating and looking down.</td>', 'Good texture and a rugged portrait! It seems you have caught the gentleman during a pause in the action. With the composition you have created, I would like to see the man intentionally looking into the distance or in action somehow focused in the direction he is looking. He just seems to be contemplating and looking down.', '2011-01-19 08:31:18.000000', NULL, 1),
(6287998, 930065, 108069, '<td valign="top">Extremely rich tones and colors. Looks like a bit of haloing around the tree, so this is probably tone-mapped for greater range/effects, but other than the haloing it''s pretty subtle and doesn''t feel overdone. I would have composed it differently so the branch was not in contact with the tower, but that''s me. Nice job.</td>', 'Extremely rich tones and colors. Looks like a bit of haloing around the tree, so this is probably tone-mapped for greater range/effects, but other than the haloing it''s pretty subtle and doesn''t feel overdone. I would have composed it differently so the branch was not in contact with the tower, but that''s me. Nice job.', '2011-01-19 08:32:54.000000', NULL, 1),
(6288000, 930692, 108069, '<td valign="top">Nice! What a great idea. Extrmemly pleasing image. If I had been at the controls I would have played with the perspective in post processing to square the windows and door frame with the photo frame, but that''s me. Otherwise the tones are great and it''s a very nice entry.</td>', 'Nice! What a great idea. Extrmemly pleasing image. If I had been at the controls I would have played with the perspective in post processing to square the windows and door frame with the photo frame, but that''s me. Otherwise the tones are great and it''s a very nice entry.', '2011-01-19 08:34:59.000000', NULL, 1),
(6288005, 930758, 121160, '<td valign="top">well taken = 8</td>', 'well taken = 8', '2011-01-19 08:44:19.000000', NULL, 1),
(6288008, 930802, 121160, '<td valign="top">Nicelly composed for what the subject is... - 8</td>', 'Nicelly composed for what the subject is... - 8', '2011-01-19 08:46:38.000000', NULL, 1),
(6288018, 930805, 2861, '<td valign="top">I wonder if you could have moved in some way do that the tree branches could have been higher in the photo and been a frame for the church. I feel I want to see what that spire looks like. If we could just move the world around so that our pictures are easier to take it would be so good.</td>', 'I wonder if you could have moved in some way do that the tree branches could have been higher in the photo and been a frame for the church. I feel I want to see what that spire looks like. If we could just move the world around so that our pictures are easier to take it would be so good.', '2011-01-19 08:54:24.000000', NULL, 1),
(6288027, 930401, 99263, '<td valign="top">Delightful composition with delicious textures and colors.</td>', 'Delightful composition with delicious textures and colors.', '2011-01-19 09:02:21.000000', NULL, 1),
(6288028, 930387, 99263, '<td valign="top">Great image and nice processing but he''s not 100 years old.</td>', 'Great image and nice processing but he''s not 100 years old.', '2011-01-19 09:04:32.000000', NULL, 1),
(6288029, 930531, 99263, '<td valign="top">A ticky....I used to have a few once upon a time. What''s that one worth?</td>', 'A ticky....I used to have a few once upon a time. What''s that one worth?', '2011-01-19 09:07:45.000000', NULL, 1),
(6288030, 930004, 99263, '<td valign="top">Lovely evening shot and nice natural framing.</td>', 'Lovely evening shot and nice natural framing.', '2011-01-19 09:08:24.000000', NULL, 1),
(6288033, 929918, 99263, '<td valign="top">Cool shot</td>', 'Cool shot', '2011-01-19 09:12:35.000000', NULL, 1),
(6288035, 930711, 99263, '<td valign="top">Pretty dramatic looking image. The moon almost looks like our blue planet earth here.</td>', 'Pretty dramatic looking image. The moon almost looks like our blue planet earth here.', '2011-01-19 09:14:29.000000', NULL, 1),
(6288036, 929810, 99263, '<td valign="top">Hmmmm interesting. Is it for real...the name of the hotel I mean? And do paranormal things happen there?</td>', 'Hmmmm interesting. Is it for real...the name of the hotel I mean? And do paranormal things happen there?', '2011-01-19 09:15:36.000000', NULL, 1),
(6288038, 930060, 99263, '<td valign="top">Interesting looking place. Nicely photographed.</td>', 'Interesting looking place. Nicely photographed.', '2011-01-19 09:16:48.000000', NULL, 1),
(6288040, 930587, 99263, '<td valign="top">Wow she does look at least 100 years old. Lovely fine detail.</td>', 'Wow she does look at least 100 years old. Lovely fine detail.', '2011-01-19 09:20:46.000000', NULL, 1),
(6288042, 930770, 103170, '<td valign="top">Sugar Mill Gardens in Port Orange?<br/>I just randomly came across this photo, I live in NSB. :)<br/>Beautiful shot.</td>', 'Sugar Mill Gardens in Port Orange?I just randomly came across this photo, I live in NSB. :)Beautiful shot.', '2011-01-19 09:21:03.000000', NULL, 1),
(6288043, 929970, 99263, '<td valign="top">Lovely detailed moon shot.</td>', 'Lovely detailed moon shot.', '2011-01-19 09:22:26.000000', NULL, 1),
(6288051, 930727, 99263, '<td valign="top">Nice natural frame and wide angle.</td>', 'Nice natural frame and wide angle.', '2011-01-19 09:29:17.000000', NULL, 1),
(6288052, 930711, 124346, '<td valign="top">Is that moon real?  Does it look so big?</td>', 'Is that moon real?  Does it look so big?', '2011-01-19 09:29:59.000000', NULL, 1),
(6288053, 930004, 124346, '<td valign="top">The tree distract too much.</td>', 'The tree distract too much.', '2011-01-19 09:32:07.000000', NULL, 1),
(6288055, 930785, 99263, '<td valign="top">Cool shot. I love those old Victorian style buildings. In South Africa you find lots of them too and this scene which I guess has been photographed in Australia could have been taken in one of the cities or towns in South Africa too.</td>', 'Cool shot. I love those old Victorian style buildings. In South Africa you find lots of them too and this scene which I guess has been photographed in Australia could have been taken in one of the cities or towns in South Africa too.', '2011-01-19 09:33:31.000000', NULL, 1),
(6288056, 929897, 99263, '<td valign="top">Very nice image</td>', 'Very nice image', '2011-01-19 09:33:50.000000', NULL, 1),
(6288057, 930789, 124346, '<td valign="top">A better composition could be done.</td>', 'A better composition could be done.', '2011-01-19 09:34:03.000000', NULL, 1),
(6288058, 930705, 99263, '<td valign="top">Lovely image exuding a certain element of mystique.</td>', 'Lovely image exuding a certain element of mystique.', '2011-01-19 09:34:49.000000', NULL, 1),
(6288061, 930723, 99263, '<td valign="top">Great crop, nice contrast and lighting.</td>', 'Great crop, nice contrast and lighting.', '2011-01-19 09:35:55.000000', NULL, 1),
(6288062, 930532, 99263, '<td valign="top">Racy shot. Nice.</td>', 'Racy shot. Nice.', '2011-01-19 09:36:28.000000', NULL, 1),
(6288063, 930456, 99263, '<td valign="top">Cool colors and textures.</td>', 'Cool colors and textures.', '2011-01-19 09:37:35.000000', NULL, 1),
(6288067, 930773, 108069, '<td valign="top">Stunning photograph but I''m dying to fix the horizon. This is especially apparent with the borders framing it. One of these horizontal lines doesn''t match. Otherwise it''s a wonderful idea and truly lovely processing.</td>', 'Stunning photograph but I''m dying to fix the horizon. This is especially apparent with the borders framing it. One of these horizontal lines doesn''t match. Otherwise it''s a wonderful idea and truly lovely processing.', '2011-01-19 09:40:26.000000', NULL, 1),
(6288068, 930542, 99263, '<td valign="top">Great wide angle shot. Nice processing.</td>', 'Great wide angle shot. Nice processing.', '2011-01-19 09:40:54.000000', NULL, 1),
(6288072, 930254, 99263, '<td valign="top">Beautiful image. I love these snow shots as so often they look like graphic art. Nice fine detail too.</td>', 'Beautiful image. I love these snow shots as so often they look like graphic art. Nice fine detail too.', '2011-01-19 09:42:02.000000', NULL, 1),
(6288073, 930807, 99263, '<td valign="top">I like the ripple effect created by shooting through... I guess a window pane with rippled glass. Very nice.</td>', 'I like the ripple effect created by shooting through... I guess a window pane with rippled glass. Very nice.', '2011-01-19 09:43:24.000000', NULL, 1),
(6288075, 930461, 99263, '<td valign="top">Good lighting.</td>', 'Good lighting.', '2011-01-19 09:45:15.000000', NULL, 1),
(6288078, 930639, 99263, '<td valign="top">I like the bold vertical lines effect created by the architecture.</td>', 'I like the bold vertical lines effect created by the architecture.', '2011-01-19 09:46:43.000000', NULL, 1),
(6288083, 930322, 108069, '<td valign="top">Great photo. The branch is slightly distracting and I would have tried to duck under it, but it is a great perspective and should do really well.</td>', 'Great photo. The branch is slightly distracting and I would have tried to duck under it, but it is a great perspective and should do really well.', '2011-01-19 09:48:40.000000', NULL, 1),
(6288098, 930040, 108069, '<td valign="top">Great perspective and shallow depth of field. Interesting scene in the background that is just kept a mystery as you''ve got the viewer focusing on what truly matters: the date. Excellent idea and perfect execution.</td>', 'Great perspective and shallow depth of field. Interesting scene in the background that is just kept a mystery as you''ve got the viewer focusing on what truly matters: the date. Excellent idea and perfect execution.', '2011-01-19 09:56:16.000000', NULL, 1),
(6288101, 930663, 108069, '<td valign="top">Nice shot. Not sure if the vignette helps or not, and I''d tweak it to the right just a hair or two, but you can''t go wrong with the subject. Nice one.</td>', 'Nice shot. Not sure if the vignette helps or not, and I''d tweak it to the right just a hair or two, but you can''t go wrong with the subject. Nice one.', '2011-01-19 10:03:00.000000', NULL, 1),
(6288117, 930435, 108069, '<td valign="top">Great color and tones here. So sharp, especially assuming it''s a hand-held job. Great idea and very well done.</td>', 'Great color and tones here. So sharp, especially assuming it''s a hand-held job. Great idea and very well done.', '2011-01-19 10:17:16.000000', NULL, 1),
(6288121, 930476, 108069, '<td valign="top">This is great. It reminds me of many clubs I''ve been to. Great composition, great colors, great exposure. Awesome.</td>', 'This is great. It reminds me of many clubs I''ve been to. Great composition, great colors, great exposure. Awesome.', '2011-01-19 10:19:05.000000', NULL, 1),
(6288123, 930247, 68020, '<td valign="top">"Ahhhh, if it tisn''t Paddy O''Brien!" This would be a great thing to have if it was one of your ancestors! - 8</td>', '"Ahhhh, if it tisn''t Paddy O''Brien!" This would be a great thing to have if it was one of your ancestors! - 8', '2011-01-19 10:22:57.000000', NULL, 1),
(6288136, 930436, 68020, '<td valign="top">Very cool camera! I would like to see it a little more in focus though</td>', 'Very cool camera! I would like to see it a little more in focus though', '2011-01-19 10:41:10.000000', NULL, 1),
(6288137, 930219, 49359, '<td valign="top">What a strange wall...</td>', 'What a strange wall...', '2011-01-19 10:41:10.000000', NULL, 1),
(6288139, 930104, 49359, '<td valign="top">Not an amazingly engaging photo. Maybe a different angle would have been better than looking at it dead on.</td>', 'Not an amazingly engaging photo. Maybe a different angle would have been better than looking at it dead on.', '2011-01-19 10:42:50.000000', NULL, 1),
(6288141, 930790, 49359, '<td valign="top">You''re.. shaking an apple?</td>', 'You''re.. shaking an apple?', '2011-01-19 10:43:49.000000', NULL, 1),
(6288142, 930456, 36843, '<td valign="top">Love the light</td>', 'Love the light', '2011-01-19 10:45:05.000000', NULL, 1),
(6288145, 930701, 49359, '<td valign="top">Lovely textures.</td>', 'Lovely textures.', '2011-01-19 10:47:15.000000', NULL, 1),
(6288149, 929957, 49359, '<td valign="top">More symmetry in the picture would have been nice.</td>', 'More symmetry in the picture would have been nice.', '2011-01-19 10:48:27.000000', NULL, 1),
(6288151, 930630, 10785, '<td valign="top">You almost have a still life setting on top of the object you photographed for the challenge! It would have been cute to arrange the objects on top to create a still life.</td>', 'You almost have a still life setting on top of the object you photographed for the challenge! It would have been cute to arrange the objects on top to create a still life.', '2011-01-19 10:49:54.000000', NULL, 1),
(6288152, 930630, 49359, '<td valign="top">I''m sure pink posies and half a bowl of oranges aren''t really necessary to the composition...</td>', 'I''m sure pink posies and half a bowl of oranges aren''t really necessary to the composition...', '2011-01-19 10:49:57.000000', NULL, 1),
(6288155, 930445, 10785, '<td valign="top">Sharp, crisp, great texture and lovely golden hues! The depth of the top of the coin is shown with the petina but not by shadows.</td>', 'Sharp, crisp, great texture and lovely golden hues! The depth of the top of the coin is shown with the petina but not by shadows.', '2011-01-19 10:50:51.000000', NULL, 1),
(6288157, 930433, 10785, '<td valign="top">Very nice detail shot. It would be great as part of a series. Standing alone it doesn''t really tell the story of the object shot.</td>', 'Very nice detail shot. It would be great as part of a series. Standing alone it doesn''t really tell the story of the object shot.', '2011-01-19 10:51:54.000000', NULL, 1),
(6288158, 930401, 36843, '<td valign="top">Nice</td>', 'Nice', '2011-01-19 10:52:14.000000', NULL, 1),
(6288160, 930194, 49359, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2011-01-19 10:52:22.000000', NULL, 1),
(6288161, 930716, 10785, '<td valign="top">A great ghostly lighthouse shot! (Pinhole maybe??)</td>', 'A great ghostly lighthouse shot! (Pinhole maybe??)', '2011-01-19 10:52:35.000000', NULL, 1),
(6288162, 930802, 10785, '<td valign="top">Good focus! Nice B&amp;W conversion showing great tones and textures.</td>', 'Good focus! Nice B&W conversion showing great tones and textures.', '2011-01-19 10:53:16.000000', NULL, 1),
(6288165, 930773, 68020, '<td valign="top">Horizon is kind of tilting to the right and it''s a little soft on the edges - I gave it a 7 but it could easily be higher if it were level and a little sharper...it''s a very nice image though!</td>', 'Horizon is kind of tilting to the right and it''s a little soft on the edges - I gave it a 7 but it could easily be higher if it were level and a little sharper...it''s a very nice image though!', '2011-01-19 10:55:09.000000', NULL, 1),
(6288167, 930805, 10785, '<td valign="top">I like the trees and how you have framed the church! Great even lighting. Lots of grey tones in the snow are offset by the warmth of the window lights. It looks a little shaky as if it were hand held with a slower shutter speed though.</td>', 'I like the trees and how you have framed the church! Great even lighting. Lots of grey tones in the snow are offset by the warmth of the window lights. It looks a little shaky as if it were hand held with a slower shutter speed though.', '2011-01-19 10:55:39.000000', NULL, 1),
(6288168, 929988, 10785, '<td valign="top">Way to make a photo of a book interesting by adding depth and using the tones of the image to show off the texture!</td>', 'Way to make a photo of a book interesting by adding depth and using the tones of the image to show off the texture!', '2011-01-19 10:56:27.000000', NULL, 1),
(6288170, 930703, 38264, '<td valign="top">I love the texture the color and the action of this piece great work.</td>', 'I love the texture the color and the action of this piece great work.', '2011-01-19 10:57:38.000000', NULL, 1),
(6288172, 930407, 68020, '<td valign="top">My God that is creepy!!! But I like it!! - 8</td>', 'My God that is creepy!!! But I like it!! - 8', '2011-01-19 10:58:22.000000', NULL, 1),
(6288174, 930293, 103229, '<td valign="top">i wish there was more of an exciting sky</td>', 'i wish there was more of an exciting sky', '2011-01-19 10:59:34.000000', NULL, 1),
(6288179, 930407, 10785, '<td valign="top">I took the time to look it up and still don''t know what it is you are referring to! Bear fossils by some guy named Burgess??</td>', 'I took the time to look it up and still don''t know what it is you are referring to! Bear fossils by some guy named Burgess??', '2011-01-19 11:01:16.000000', NULL, 1),
(6288181, 930235, 10785, '<td valign="top">Beautiful composition, however the photo is somewhat overexposed in my opinion! It is beautiful though!</td>', 'Beautiful composition, however the photo is somewhat overexposed in my opinion! It is beautiful though!', '2011-01-19 11:02:09.000000', NULL, 1),
(6288184, 930600, 10785, '<td valign="top">Good color and composition. I like the lines leading you into the center of the image. This seems to be overexposed though. A little too much shutter speed! Maybe close up the aperture to shorten the exposure a hair to get more blacks and less greys!</td>', 'Good color and composition. I like the lines leading you into the center of the image. This seems to be overexposed though. A little too much shutter speed! Maybe close up the aperture to shorten the exposure a hair to get more blacks and less greys!', '2011-01-19 11:05:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6288188, 930632, 10785, '<td valign="top">It''s a great detail shot, but doesn''t convey the concept of 100 years old to me. I am sure it is the abandoned 100 year old flume, but this could be anything for all I know. It would work as part of a series of photos studying the subject, a diptych or tryptych or something, but standing alone it doesn''t convey the message.</td>', 'It''s a great detail shot, but doesn''t convey the concept of 100 years old to me. I am sure it is the abandoned 100 year old flume, but this could be anything for all I know. It would work as part of a series of photos studying the subject, a diptych or tryptych or something, but standing alone it doesn''t convey the message.', '2011-01-19 11:07:42.000000', NULL, 1),
(6288193, 930811, 54446, '<td valign="top">Very cool image, which meets the challenge well.  I especially like the context of the foreground plants &amp; snow.  It lends scale and reality to the archeology.</td>', 'Very cool image, which meets the challenge well.  I especially like the context of the foreground plants & snow.  It lends scale and reality to the archeology.', '2011-01-19 11:13:29.000000', NULL, 1),
