(6288321, 930322, 83313, '<td valign="top">A nice scene, well composed, but it seems somewhat pixelated, or oversharpened, or something.</td>', 'A nice scene, well composed, but it seems somewhat pixelated, or oversharpened, or something.', '2011-01-19 12:45:38.000000', NULL, 1),
(6288326, 930665, 23484, '<td valign="top">Very cool looking stairwell.</td>', 'Very cool looking stairwell.', '2011-01-19 12:48:04.000000', NULL, 1),
(6288327, 930696, 10785, '<td valign="top">Good clean macro, balanced lighting, a few minor bright spots in the raised areas around the eyes, texture is seen but not really the star of this shot. The clean, white background really contrasts and detracts from the old time feel of the coin. It''s good, meets the challenge, and would work well for an advertisement or product shot or an ebay auction description.</td>', 'Good clean macro, balanced lighting, a few minor bright spots in the raised areas around the eyes, texture is seen but not really the star of this shot. The clean, white background really contrasts and detracts from the old time feel of the coin. It''s good, meets the challenge, and would work well for an advertisement or product shot or an ebay auction description.', '2011-01-19 12:48:15.000000', NULL, 1),
(6288328, 930476, 23484, '<td valign="top">I like the symetry. Nice shot.</td>', 'I like the symetry. Nice shot.', '2011-01-19 12:48:21.000000', NULL, 1),
(6288329, 930436, 83313, '<td valign="top">Nice subject and lighting, but there appears to be some slight blur, perhaps it could be a touch of camera shake from a handheld shot at a low shutter speed.</td>', 'Nice subject and lighting, but there appears to be some slight blur, perhaps it could be a touch of camera shake from a handheld shot at a low shutter speed.', '2011-01-19 12:48:30.000000', NULL, 1),
(6288331, 930236, 23484, '<td valign="top">Very nice shot. I like the soft contrast.</td>', 'Very nice shot. I like the soft contrast.', '2011-01-19 12:48:53.000000', NULL, 1),
(6288332, 930456, 23484, '<td valign="top">Beautiful colors. I love that architecture.</td>', 'Beautiful colors. I love that architecture.', '2011-01-19 12:49:24.000000', NULL, 1),
