(6288666, 930596, 114285, '<td valign="top">Love this is black and white, great angle.</td>', 'Love this is black and white, great angle.', '2011-01-19 18:35:59.000000', NULL, 1),
(6288668, 930811, 108069, '<td valign="top">Very interesting. I''d have zoomed up close of the rock and/or tackled it from a different angle, as I think the foliage in the foreground is a bit distracting... though I do like the contrast with the snow and rock. Wonderfully conceived photo. Nice.</td>', 'Very interesting. I''d have zoomed up close of the rock and/or tackled it from a different angle, as I think the foliage in the foreground is a bit distracting... though I do like the contrast with the snow and rock. Wonderfully conceived photo. Nice.', '2011-01-19 18:36:05.000000', NULL, 1),
