INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6289078, 930236, 108069, '<td valign="top">Beautiful image. Reminds me of the tones and delivery of my last challenge entry, which I obviously liked but was also promptly slaughtered by voters. I hope they don''t miss the boat on this one, as it''s a wonderful photo.<br/> <br/>Delicate in tone and texture yet strong in resilience. Excellent.</td>', 'Beautiful image. Reminds me of the tones and delivery of my last challenge entry, which I obviously liked but was also promptly slaughtered by voters. I hope they don''t miss the boat on this one, as it''s a wonderful photo. Delicate in tone and texture yet strong in resilience. Excellent.', '2011-01-20 05:07:14.000000', NULL, 1),
(6289081, 930299, 108069, '<td valign="top">Nice focal point. Not jaw-dropping exciting, but very nice weathered texture, contrast, and certainly a perfect entry for this challenge.</td>', 'Nice focal point. Not jaw-dropping exciting, but very nice weathered texture, contrast, and certainly a perfect entry for this challenge.', '2011-01-20 05:13:25.000000', NULL, 1),
(6289083, 930741, 108069, '<td valign="top">Wonderfully moody. Great tones of desolation and a time forgotten and neglected by everyone, even mother nature. Great photo.</td>', 'Wonderfully moody. Great tones of desolation and a time forgotten and neglected by everyone, even mother nature. Great photo.', '2011-01-20 05:14:35.000000', NULL, 1),
(6289098, 930742, 108069, '<td valign="top">Haunting image. Incredible mood and quiet power here.</td>', 'Haunting image. Incredible mood and quiet power here.', '2011-01-20 05:41:54.000000', NULL, 1),
(6289099, 930248, 108069, '<td valign="top">Very nice composition. Nice detail in the stones, and wonderful tones. B&amp;W a good choice for this.</td>', 'Very nice composition. Nice detail in the stones, and wonderful tones. B&W a good choice for this.', '2011-01-20 05:42:46.000000', NULL, 1),
(6289100, 930662, 108069, '<td valign="top">Very nice image. Great example for the challenge. Pleasing tones and nice, easy hand on the processing. Great.</td>', 'Very nice image. Great example for the challenge. Pleasing tones and nice, easy hand on the processing. Great.', '2011-01-20 05:50:42.000000', NULL, 1),
(6289101, 930660, 108069, '<td valign="top">Beautiful image. Wonderful tones and the B&amp;W treatment brings out the detail. Certainly one of if not the best in the challenge (just getting started). Not voting, just admiring.</td>', 'Beautiful image. Wonderful tones and the B&W treatment brings out the detail. Certainly one of if not the best in the challenge (just getting started). Not voting, just admiring.', '2011-01-20 05:50:47.000000', NULL, 1),
(6289102, 930225, 108069, '<td valign="top">Wonderful focal depth. Very nicely composed. Lighting and focus give this a mood far beyond 99.99% of museum shots. Very well done.</td>', 'Wonderful focal depth. Very nicely composed. Lighting and focus give this a mood far beyond 99.99% of museum shots. Very well done.', '2011-01-20 05:53:00.000000', NULL, 1),
(6289120, 930258, 108069, '<td valign="top">Despite the cars in the background they''re not distracting thanks to the wonderful capture. A shallower depth of field would make this even better. But it''s an engaging scene. Nice.</td>', 'Despite the cars in the background they''re not distracting thanks to the wonderful capture. A shallower depth of field would make this even better. But it''s an engaging scene. Nice.', '2011-01-20 06:45:35.000000', NULL, 1),
(6289122, 930789, 108069, '<td valign="top">Nice bridge scene with rich tones on a peaceful, mirror-reflection morning. Nice composition.</td>', 'Nice bridge scene with rich tones on a peaceful, mirror-reflection morning. Nice composition.', '2011-01-20 06:51:41.000000', NULL, 1),
(6289123, 930660, 23484, '<td valign="top">I love the B&amp;W processing. Nice image.</td>', 'I love the B&W processing. Nice image.', '2011-01-20 06:52:31.000000', NULL, 1),
(6289124, 930644, 23484, '<td valign="top">The color tone works very well for this style of shot. Nice job.</td>', 'The color tone works very well for this style of shot. Nice job.', '2011-01-20 06:52:55.000000', NULL, 1),
(6289125, 930254, 23484, '<td valign="top">The composition is absolutely perfect. The snow really adds a lot to this. 9</td>', 'The composition is absolutely perfect. The snow really adds a lot to this. 9', '2011-01-20 06:54:03.000000', NULL, 1),
(6289126, 929810, 23484, '<td valign="top">Very cool looking. The processing really enhanced this.</td>', 'Very cool looking. The processing really enhanced this.', '2011-01-20 06:54:48.000000', NULL, 1),
(6289127, 929897, 108069, '<td valign="top">Really nice image with great composition. Certainly tells a story.</td>', 'Really nice image with great composition. Certainly tells a story.', '2011-01-20 06:55:30.000000', NULL, 1),
(6289128, 930703, 23484, '<td valign="top">Nicely composed shot. Neat processing.</td>', 'Nicely composed shot. Neat processing.', '2011-01-20 06:55:41.000000', NULL, 1),
(6289129, 930735, 23484, '<td valign="top">This is outstanding. I didn''t see the face at first. Great shot.10</td>', 'This is outstanding. I didn''t see the face at first. Great shot.10', '2011-01-20 06:56:46.000000', NULL, 1),
(6289130, 930742, 3585, '<td valign="top">The memory of water. <br/>How does one say "lovely" in Pimu?</td>', 'The memory of water. How does one say "lovely" in Pimu?', '2011-01-20 06:56:47.000000', NULL, 1),
(6289131, 930532, 23484, '<td valign="top">I love that architecture. Nice angles.</td>', 'I love that architecture. Nice angles.', '2011-01-20 06:57:30.000000', NULL, 1),
(6289133, 930636, 108069, '<td valign="top">Very nice landscape with a rolling mist over the hills and lovely sky. Nice line as well. I''m not a big fan of the border, as I like to see photos as large as possible, and think that this may have been better suited with a letterbox-type border to fill the screen a bit more. But I''m not voting so take that for what''s worth. Very nice scene.</td>', 'Very nice landscape with a rolling mist over the hills and lovely sky. Nice line as well. I''m not a big fan of the border, as I like to see photos as large as possible, and think that this may have been better suited with a letterbox-type border to fill the screen a bit more. But I''m not voting so take that for what''s worth. Very nice scene.', '2011-01-20 07:00:48.000000', NULL, 1),
(6289138, 930401, 108069, '<td valign="top">Awesome for this challenge. Very nice composition and a good story. Rich colors and textures. Great shot.</td>', 'Awesome for this challenge. Very nice composition and a good story. Rich colors and textures. Great shot.', '2011-01-20 07:05:31.000000', NULL, 1),
(6289139, 930698, 108069, '<td valign="top">Wonderful composition and classy shot. Beautiful joint.</td>', 'Wonderful composition and classy shot. Beautiful joint.', '2011-01-20 07:06:18.000000', NULL, 1),
(6289142, 930194, 108069, '<td valign="top">Otherworldly. Wonderful perspective and deeply intriguing. The processing may have left this not quite as sharp, but it''s a great shot regardless.</td>', 'Otherworldly. Wonderful perspective and deeply intriguing. The processing may have left this not quite as sharp, but it''s a great shot regardless.', '2011-01-20 07:10:46.000000', NULL, 1),
(6289144, 930727, 108069, '<td valign="top">Nicely framed. The foliage is a bit dark, but it''s well conceived. Adds a bit of mystery as well, imagining sneaking around to get the view.</td>', 'Nicely framed. The foliage is a bit dark, but it''s well conceived. Adds a bit of mystery as well, imagining sneaking around to get the view.', '2011-01-20 07:13:26.000000', NULL, 1),
(6289146, 929995, 108069, '<td valign="top">Very well done. Lovely tones, great exposure and treatment. Truly great.</td>', 'Very well done. Lovely tones, great exposure and treatment. Truly great.', '2011-01-20 07:18:18.000000', NULL, 1),
(6289148, 930235, 108069, '<td valign="top">Wild. Clearly old yet with the lights it almost seems like a modern arcade. Great colors and perspective. Cool photo.</td>', 'Wild. Clearly old yet with the lights it almost seems like a modern arcade. Great colors and perspective. Cool photo.', '2011-01-20 07:19:29.000000', NULL, 1),
(6289153, 930807, 108069, '<td valign="top">I honestly don''t know whether this is an overlay or a Topaz action or shot through some funky glass. Interesting, but the pattern is a bit distracting.</td>', 'I honestly don''t know whether this is an overlay or a Topaz action or shot through some funky glass. Interesting, but the pattern is a bit distracting.', '2011-01-20 07:34:24.000000', NULL, 1),
(6289156, 930737, 108069, '<td valign="top">Nicely composed. Nice collection. Over a century of wear and tear and the texture shows it. Nice.</td>', 'Nicely composed. Nice collection. Over a century of wear and tear and the texture shows it. Nice.', '2011-01-20 07:48:47.000000', NULL, 1),
(6289159, 930701, 108069, '<td valign="top">Nice idea. The focus seems slightly harsh to me, however, like there''s not enough background to offset the in-focus ring against the slightly OOF door. I think I maybe would have pulled back a bit. With the ring in focus it still would have made a great subject. Rich colors. Nice.</td>', 'Nice idea. The focus seems slightly harsh to me, however, like there''s not enough background to offset the in-focus ring against the slightly OOF door. I think I maybe would have pulled back a bit. With the ring in focus it still would have made a great subject. Rich colors. Nice.', '2011-01-20 07:59:33.000000', NULL, 1),
(6289161, 930596, 108069, '<td valign="top">Nice composition. Not entirely sold on the B&amp;W as I feel it lacks some contrast. Maybe if there was a wider tonal range, but it feels safely in the middle. Very nice shot though.</td>', 'Nice composition. Not entirely sold on the B&W as I feel it lacks some contrast. Maybe if there was a wider tonal range, but it feels safely in the middle. Very nice shot though.', '2011-01-20 08:02:59.000000', NULL, 1),
(6289164, 930446, 108069, '<td valign="top">Nice crisp colors and clarity. Nice perspective as it seems to be blooming from the ground. Well composed, lovely tones in the sky. Great shot.</td>', 'Nice crisp colors and clarity. Nice perspective as it seems to be blooming from the ground. Well composed, lovely tones in the sky. Great shot.', '2011-01-20 08:05:52.000000', NULL, 1),
(6289165, 930707, 108069, '<td valign="top">Well lit and composed. Would love to know the story behind it.</td>', 'Well lit and composed. Would love to know the story behind it.', '2011-01-20 08:08:15.000000', NULL, 1),
(6289168, 929843, 108069, '<td valign="top">Great composition and use of natural framing. Nice tones and texture. Very well done.</td>', 'Great composition and use of natural framing. Nice tones and texture. Very well done.', '2011-01-20 08:10:46.000000', NULL, 1),
(6289175, 930254, 108069, '<td valign="top">Wonderful photo. Truly a beautiful scene of an iconic symbol. Awesome.</td>', 'Wonderful photo. Truly a beautiful scene of an iconic symbol. Awesome.', '2011-01-20 08:21:19.000000', NULL, 1),
(6289176, 930104, 108069, '<td valign="top">Very well composed and framed. Great contrast between the rich door and the aged siding. Well done.</td>', 'Very well composed and framed. Great contrast between the rich door and the aged siding. Well done.', '2011-01-20 08:22:31.000000', NULL, 1),
(6289180, 930769, 108069, '<td valign="top">Creepy. Nice focus manipulation and contrast shift to isolate the subject. Well composed. Great shot.</td>', 'Creepy. Nice focus manipulation and contrast shift to isolate the subject. Well composed. Great shot.', '2011-01-20 08:40:50.000000', NULL, 1),
(6289181, 930217, 108069, '<td valign="top">Always flowing, always cutting, always there. Nice interpretation of the challenge. I like the B&amp;W but I''d somehow like to see a broader range of tones. Maybe some shadows/highlights work would bring out some grays. Nice one though.</td>', 'Always flowing, always cutting, always there. Nice interpretation of the challenge. I like the B&W but I''d somehow like to see a broader range of tones. Maybe some shadows/highlights work would bring out some grays. Nice one though.', '2011-01-20 08:42:14.000000', NULL, 1),
(6289182, 929918, 108069, '<td valign="top">Nice lines and mood. Interesting perspective. Great composition.</td>', 'Nice lines and mood. Interesting perspective. Great composition.', '2011-01-20 08:45:13.000000', NULL, 1),
(6289183, 930247, 108069, '<td valign="top">Wow, what a find. Great subject. Perfect for the theme, with a lot of meaning and a great story. Exposed well and nice composition. Great entry.</td>', 'Wow, what a find. Great subject. Perfect for the theme, with a lot of meaning and a great story. Exposed well and nice composition. Great entry.', '2011-01-20 08:48:14.000000', NULL, 1),
(6289186, 930711, 108069, '<td valign="top">Dramatic. I''m concerned this has been done with two captures, however. I''m not voting, but obviously the size of the moon leads me to believe that some creative use of zoom has been applied. Regardless, your subject is nicely chosen and it''s a very interesting scene.</td>', 'Dramatic. I''m concerned this has been done with two captures, however. I''m not voting, but obviously the size of the moon leads me to believe that some creative use of zoom has been applied. Regardless, your subject is nicely chosen and it''s a very interesting scene.', '2011-01-20 08:50:57.000000', NULL, 1),
(6289189, 929981, 108069, '<td valign="top">The reflections were distracting before I realized the masts tied it in with sailing (even more). Nice concept.</td>', 'The reflections were distracting before I realized the masts tied it in with sailing (even more). Nice concept.', '2011-01-20 08:52:25.000000', NULL, 1),
(6289201, 930165, 58667, '<td valign="top">I like the composition, but the photo is a bit skew. Ever so slightly, but my eyes noticed it immediately, and since it is skew to the left, the arm swinging to the left also puts it off balance. -1 for that so 6.</td>', 'I like the composition, but the photo is a bit skew. Ever so slightly, but my eyes noticed it immediately, and since it is skew to the left, the arm swinging to the left also puts it off balance. -1 for that so 6.', '2011-01-20 09:36:11.000000', NULL, 1),
(6289202, 930531, 58667, '<td valign="top">I love the composition. The only thing is that the photo could have been a bit bigger. One of my favourite coin shots in the challenge!</td>', 'I love the composition. The only thing is that the photo could have been a bit bigger. One of my favourite coin shots in the challenge!', '2011-01-20 09:38:18.000000', NULL, 1),
(6289206, 930587, 61961, '<td valign="top">OK, so I don''t believe she is 100, but it''s a nice candid.</td>', 'OK, so I don''t believe she is 100, but it''s a nice candid.', '2011-01-20 09:43:12.000000', NULL, 1),
(6289210, 930060, 126652, '<td valign="top">I love the balance of saturation, and how it contrasts with the desaturated parts of the photograph.</td>', 'I love the balance of saturation, and how it contrasts with the desaturated parts of the photograph.', '2011-01-20 09:53:37.000000', NULL, 1),
(6289215, 930542, 126652, '<td valign="top">Every aspect of this photograph catches my eye and makes me believe this is as close to perfection as a photo can be...from the pattern of the fence posts, to the slight focus on the puppy, and the detail in the sky and on the porch.</td>', 'Every aspect of this photograph catches my eye and makes me believe this is as close to perfection as a photo can be...from the pattern of the fence posts, to the slight focus on the puppy, and the detail in the sky and on the porch.', '2011-01-20 09:58:50.000000', NULL, 1),
(6289218, 930461, 126652, '<td valign="top">The isolation of the subject creates a feeling of focus and serenity. A very good choice.</td>', 'The isolation of the subject creates a feeling of focus and serenity. A very good choice.', '2011-01-20 10:04:19.000000', NULL, 1),
(6289238, 930444, 113156, '<td valign="top">Fantastic b&amp;w the lady''s expression is priceless, By far my favorite in this challenge.</td>', 'Fantastic b&w the lady''s expression is priceless, By far my favorite in this challenge.', '2011-01-20 10:29:56.000000', NULL, 1),
(6289287, 930696, 108069, '<td valign="top">Nice find. Weathered and worn. Nice sharp focus.</td>', 'Nice find. Weathered and worn. Nice sharp focus.', '2011-01-20 11:46:55.000000', NULL, 1),
(6289290, 930444, 108069, '<td valign="top">Nice ghostlike treatment. Moody tones and grain. Great photo.</td>', 'Nice ghostlike treatment. Moody tones and grain. Great photo.', '2011-01-20 11:47:51.000000', NULL, 1),
(6289292, 930590, 108069, '<td valign="top">Nice scene. I enjoy the white sky, as if the house and tree are fighting to continue to remain on this planet. Reality fades into nothing. Very old-timey feel. Well done.</td>', 'Nice scene. I enjoy the white sky, as if the house and tree are fighting to continue to remain on this planet. Reality fades into nothing. Very old-timey feel. Well done.', '2011-01-20 11:49:39.000000', NULL, 1),
(6289294, 929936, 108069, '<td valign="top">Excellent photo. So detailed and sharp. Great composition. Excellent entry for this challenge.</td>', 'Excellent photo. So detailed and sharp. Great composition. Excellent entry for this challenge.', '2011-01-20 11:50:31.000000', NULL, 1),
(6289297, 930504, 108069, '<td valign="top">Great profile. Nice composition. Processing really accentuates the haggard feel. Well done.</td>', 'Great profile. Nice composition. Processing really accentuates the haggard feel. Well done.', '2011-01-20 11:54:50.000000', NULL, 1),
(6289298, 930493, 108069, '<td valign="top">Nice processing to make it feel as old as the camera. Excellent focal depth. Very nice photo.</td>', 'Nice processing to make it feel as old as the camera. Excellent focal depth. Very nice photo.', '2011-01-20 11:55:31.000000', NULL, 1),
(6289339, 930532, 118154, '<td valign="top">Nice image,one of my top picks in this challenge.</td>', 'Nice image,one of my top picks in this challenge.', '2011-01-20 12:56:01.000000', NULL, 1),
(6289340, 930639, 23484, '<td valign="top">That is some gorgeous architecture. Beautiful shot.</td>', 'That is some gorgeous architecture. Beautiful shot.', '2011-01-20 12:56:10.000000', NULL, 1),
(6289343, 930716, 23484, '<td valign="top">The processing is cool.</td>', 'The processing is cool.', '2011-01-20 12:56:32.000000', NULL, 1),
(6289344, 930336, 108069, '<td valign="top">Nice shot. The red stone really stands apart from the surrounding glass structures. Nice and sharp. I struggle with making these upward-looking shots of buildings look normal due to perspective shifts but this is really done well. Great example for this challenge.</td>', 'Nice shot. The red stone really stands apart from the surrounding glass structures. Nice and sharp. I struggle with making these upward-looking shots of buildings look normal due to perspective shifts but this is really done well. Great example for this challenge.', '2011-01-20 12:56:38.000000', NULL, 1),
(6289345, 930723, 23484, '<td valign="top">Great macro shot. Perfect lighting.</td>', 'Great macro shot. Perfect lighting.', '2011-01-20 12:56:58.000000', NULL, 1),
(6289347, 929777, 108069, '<td valign="top">Beautiful reflection. Story there with the couple holding hands. Nice composition.</td>', 'Beautiful reflection. Story there with the couple holding hands. Nice composition.', '2011-01-20 12:58:22.000000', NULL, 1),
(6289360, 930389, 83313, '<td valign="top">Not getting it. Is the dried flower 100 years old? I''ll have to give the benefit of the doubt on this one, even though the connection is not totally clear to me.</td>', 'Not getting it. Is the dried flower 100 years old? I''ll have to give the benefit of the doubt on this one, even though the connection is not totally clear to me.', '2011-01-20 13:16:03.000000', NULL, 1),
(6289365, 930735, 10785, '<td valign="top">I must be not be enlightened enough to understand what the photographer is trying to communicate in the photo. Somewhat of a cross with a globe of light and a face peeking through... hmmm. 100 years old, cross, light, face, ghostly... Nope, not getting it. Scratching my head though.<br/> <br/>Edited to add: It is a fine image with artistic merit. The grainy, ghostly feel leaves one with the sense that it is depicting the spirit world. A rift is opening up and one is seeing into it or something is coming out of it. This photo would otherwise score well in my opinion if it were in a different challenge. I don''t think it fits well into this particular challenge though.</td>', 'I must be not be enlightened enough to understand what the photographer is trying to communicate in the photo. Somewhat of a cross with a globe of light and a face peeking through... hmmm. 100 years old, cross, light, face, ghostly... Nope, not getting it. Scratching my head though. Edited to add: It is a fine image with artistic merit. The grainy, ghostly feel leaves one with the sense that it is depicting the spirit world. A rift is opening up and one is seeing into it or something is coming out of it. This photo would otherwise score well in my opinion if it were in a different challenge. I don''t think it fits well into this particular challenge though.', '2011-01-20 13:21:10.000000', NULL, 1),
(6289367, 930600, 83313, '<td valign="top">I don''t see anything in this scene that appears to be 100 years old. No doubt you are submitting that the city itself is over 100 years old. I''m having a very hard time deciding if these modern cityscapes suit the topic. If the scene centered around an old clock tower or courthouse, that would be different. For now, it gets a neutral 5 from me.</td>', 'I don''t see anything in this scene that appears to be 100 years old. No doubt you are submitting that the city itself is over 100 years old. I''m having a very hard time deciding if these modern cityscapes suit the topic. If the scene centered around an old clock tower or courthouse, that would be different. For now, it gets a neutral 5 from me.', '2011-01-20 13:24:14.000000', NULL, 1),
(6289374, 930715, 83313, '<td valign="top">Some minor blur and ISO noise is a problem for what what otherwise might have worked for me. The blur could be camera shake from a very low shutter speed.</td>', 'Some minor blur and ISO noise is a problem for what what otherwise might have worked for me. The blur could be camera shake from a very low shutter speed.', '2011-01-20 13:28:20.000000', NULL, 1),
(6289380, 930638, 108069, '<td valign="top">Nice contrast. I''d hope for just a bit more detail in the stones/fort, but the composition is nice, and I like the way it is offset against the stark sky.</td>', 'Nice contrast. I''d hope for just a bit more detail in the stones/fort, but the composition is nice, and I like the way it is offset against the stark sky.', '2011-01-20 13:46:56.000000', NULL, 1),
(6289382, 930324, 108069, '<td valign="top">Slightly awkward angle of shot but a very nice subject and nice tones and contrast.</td>', 'Slightly awkward angle of shot but a very nice subject and nice tones and contrast.', '2011-01-20 13:48:23.000000', NULL, 1),
(6289383, 930717, 108069, '<td valign="top">Like a faded postcard of another era. I really like the light distribution across the church due to the clouds and trees. Peaceful memorial. Very nice.</td>', 'Like a faded postcard of another era. I really like the light distribution across the church due to the clouds and trees. Peaceful memorial. Very nice.', '2011-01-20 13:50:58.000000', NULL, 1),
(6289384, 930499, 108069, '<td valign="top">I really like the processing here. Reminds me of a futuristic environment in negative animation land. Great contrast of the stone against the wonderful sky. Surreal.</td>', 'I really like the processing here. Reminds me of a futuristic environment in negative animation land. Great contrast of the stone against the wonderful sky. Surreal.', '2011-01-20 13:55:41.000000', NULL, 1),
(6289386, 930389, 108069, '<td valign="top">Nice portrait. The tones are well tied together and the processing is excellent. Very nice how the sharpness smoothes out by the time we get to her collarbone. Keeps your focus on her eyes and the rose. I''d wager, however, that most voters will not be able to make the connection with the challenge theme. Not voting, just commenting.</td>', 'Nice portrait. The tones are well tied together and the processing is excellent. Very nice how the sharpness smoothes out by the time we get to her collarbone. Keeps your focus on her eyes and the rose. I''d wager, however, that most voters will not be able to make the connection with the challenge theme. Not voting, just commenting.', '2011-01-20 13:58:59.000000', NULL, 1),
(6289387, 930387, 108069, '<td valign="top">Are you sure he''s sleeping?! Get a mirror!<br/> <br/>Just kidding of course, no intention to offend. Certainly sends the message of multiple decades gone by. Very nice composition and crisp and thoughtful processing to preserve the color but with a fade just enough to reinforce the aged attributes. Very well done.</td>', 'Are you sure he''s sleeping?! Get a mirror! Just kidding of course, no intention to offend. Certainly sends the message of multiple decades gone by. Very nice composition and crisp and thoughtful processing to preserve the color but with a fade just enough to reinforce the aged attributes. Very well done.', '2011-01-20 14:02:04.000000', NULL, 1),
(6289388, 930723, 108069, '<td valign="top">Nice composition/crop. Great detail and texture. Over a century of nicks. Nice.</td>', 'Nice composition/crop. Great detail and texture. Over a century of nicks. Nice.', '2011-01-20 14:03:14.000000', NULL, 1),
(6289392, 930073, 108069, '<td valign="top">Nice range of exposure and very nice composition. Interesting subject that''s perfect for the theme. Well done.</td>', 'Nice range of exposure and very nice composition. Interesting subject that''s perfect for the theme. Well done.', '2011-01-20 14:11:28.000000', NULL, 1),
(6289394, 930770, 108069, '<td valign="top">Beautiful image. Wonderful range of green tones and exposures. Very nice composition. I can really feel this photo... and it sure as hell beats the cold outside. Great job.</td>', 'Beautiful image. Wonderful range of green tones and exposures. Very nice composition. I can really feel this photo... and it sure as hell beats the cold outside. Great job.', '2011-01-20 14:13:01.000000', NULL, 1),
(6289396, 930494, 108069, '<td valign="top">Nice composition and good idea. I think a wider dynamic range to show off more of the fading sun''s colors as well as the depp, dark blue of the sky fading into night would really make this stand out. This is a beautiful, peaceful scene.</td>', 'Nice composition and good idea. I think a wider dynamic range to show off more of the fading sun''s colors as well as the depp, dark blue of the sky fading into night would really make this stand out. This is a beautiful, peaceful scene.', '2011-01-20 14:15:30.000000', NULL, 1),
(6289397, 930403, 108069, '<td valign="top">Nice capture. I think a bit more local contrast would make this jump a bit more, but it''s a great subject and the composition is just right. Nice.</td>', 'Nice capture. I think a bit more local contrast would make this jump a bit more, but it''s a great subject and the composition is just right. Nice.', '2011-01-20 14:17:06.000000', NULL, 1),
(6289400, 929810, 108069, '<td valign="top">Wonderful interior shot. Great composition that displays it all with everything squared up. Nice processing that provides a wide range of exposure while not coming off fake. Perfect subject. Very well done.</td>', 'Wonderful interior shot. Great composition that displays it all with everything squared up. Nice processing that provides a wide range of exposure while not coming off fake. Perfect subject. Very well done.', '2011-01-20 14:19:25.000000', NULL, 1),
(6289401, 930761, 108069, '<td valign="top">Nice view. With different light (hitting the entire face) this would be even better. Nice tones and contrast.</td>', 'Nice view. With different light (hitting the entire face) this would be even better. Nice tones and contrast.', '2011-01-20 14:20:32.000000', NULL, 1),
(6289403, 930004, 108069, '<td valign="top">Beautiful and dramatic tones to the sky and its reflection. Nice cityscape. Great composition and lighting on the foreground tree and brush. Wonderful shot.</td>', 'Beautiful and dramatic tones to the sky and its reflection. Nice cityscape. Great composition and lighting on the foreground tree and brush. Wonderful shot.', '2011-01-20 14:22:03.000000', NULL, 1),
(6289409, 930694, 108069, '<td valign="top">Good idea. I think this would be even better with more contrast between the clouds and blue sky, and greater detail in the stonework. I think greater contrast in general, possibly warmer WB as well. It''s clean and nice, but with some dramatic punch it''d be great. Of course there''s also the small matter of straightening it a bit, but still a very well conceived entry.</td>', 'Good idea. I think this would be even better with more contrast between the clouds and blue sky, and greater detail in the stonework. I think greater contrast in general, possibly warmer WB as well. It''s clean and nice, but with some dramatic punch it''d be great. Of course there''s also the small matter of straightening it a bit, but still a very well conceived entry.', '2011-01-20 14:27:10.000000', NULL, 1),
(6289411, 929914, 108069, '<td valign="top">Nice idea. Too bad you didn''t have any Augustiner Edelstoff lying around to fill that thing. Still, it looks like cleaning up the shoot was fun.</td>', 'Nice idea. Too bad you didn''t have any Augustiner Edelstoff lying around to fill that thing. Still, it looks like cleaning up the shoot was fun.', '2011-01-20 14:29:27.000000', NULL, 1),
