(6289439, 929957, 108069, '<td valign="top">Crisp, clean and sharp, with nice colors and tones. Nice composition. Great idea.</td>', 'Crisp, clean and sharp, with nice colors and tones. Nice composition. Great idea.', '2011-01-20 14:56:47.000000', NULL, 1),
