(6289978, 930735, 11769, '<td valign="top">This captures the feeling of the fragility of our existence so perfectly. A door cracked open just enough to see the fleeting image of a child passing. Time is so brutal as it sweeps us all away.<br/>Did I say I love this?</td>', 'This captures the feeling of the fragility of our existence so perfectly. A door cracked open just enough to see the fleeting image of a child passing. Time is so brutal as it sweeps us all away.Did I say I love this?', '2011-01-21 10:10:24.000000', NULL, 1),
(6289980, 930373, 11769, '<td valign="top">Wow. Sol blasting light upon planet Earth. To see Light in a different way. Love the color. The chaos. The dirty lens is beautiful.</td>', 'Wow. Sol blasting light upon planet Earth. To see Light in a different way. Love the color. The chaos. The dirty lens is beautiful.', '2011-01-21 10:18:18.000000', NULL, 1),
